// Parse incoming Noel request and extract endpoint
const input = $input.first().json;
// Webhook wraps POST data in .body property
const requestData = input.body || input;
const endpoint = requestData.endpoint || 'unknown';

return [{
  json: {
    endpoint: endpoint,
    payload: requestData
  }
}];

// Capture Learning - Prepare Notion payload
const payload = $input.first().json.payload;
const now = new Date().toISOString();

// Build Notion page properties
const properties = {
  'Title': {
    title: [{ text: { content: payload.title || 'Untitled Learning' } }]
  },
  'Type': {
    select: { name: payload.type || 'technical' }
  },
  'Content': {
    rich_text: [{ text: { content: payload.content || '' } }]
  },
  'Context': {
    rich_text: [{ text: { content: payload.context || '' } }]
  },
  'Confidence': {
    select: { name: payload.confidence || 'medium' }
  },
  'Status': {
    select: { name: 'Active' }
  },
  'Timestamp': {
    date: { start: now }
  },
  'Last Modified': {
    date: { start: now }
  },
  'AI Suggested': {
    checkbox: payload.ai_suggested || false
  },
  'AI Accepted': {
    checkbox: false
  }
};

// Add optional fields
if (payload.dev_stream && Array.isArray(payload.dev_stream)) {
  properties['Dev Stream'] = {
    multi_select: payload.dev_stream.map(s => ({ name: s }))
  };
}

if (payload.tags && Array.isArray(payload.tags)) {
  properties['Tags'] = {
    multi_select: payload.tags.map(t => ({ name: t }))
  };
}

if (payload.related_files) {
  properties['Related Files'] = {
    rich_text: [{ text: { content: payload.related_files } }]
  };
}

// Project relation (requires page ID)
if (payload.project_id) {
  properties['Project'] = {
    relation: [{ id: payload.project_id }]
  };
}

// Session relation (requires page ID)
if (payload.session_id) {
  properties['Session'] = {
    relation: [{ id: payload.session_id }]
  };
}

// Source channel tracking (telegram, slack, cli, claude-code, api)
if (payload.source_channel) {
  properties['Source Channel'] = {
    select: { name: payload.source_channel }
  };
}

return [{
  json: {
    title: payload.title,
    notion_payload: {
      parent: { data_source_id: '2b23d603-acb6-8001-983a-000b5df4e3b7' },
      properties: properties
    }
  }
}];

// Update Learning - Step 1: Query Notion to find page by Title (Learning ID)
const payload = $input.first().json.payload;

// The learning_id IS the title in Notion
// Query by Title field (title property uses different filter syntax)
return [{
  json: {
    query: {
      endpoint: 'query_data_source',
      id: '2b23d603-acb6-8001-983a-000b5df4e3b7'
    },
    body: {
      filter: {
        property: 'Title',
        title: {
          equals: payload.learning_id  // Changed from payload.title
        }
      },
      page_size: 1
    },
    update_payload: payload  // Store for next step
  }
}];

// Start Session - Generate Session ID and prepare Notion payload
const payload = $input.first().json.payload;
const now = new Date().toISOString();

// Generate Session ID: YYYYMMDD-HHMM-project
const date = new Date();
const dateStr = date.toISOString().slice(0,10).replace(/-/g, '');
const timeStr = date.toISOString().slice(11,16).replace(/:/g, '');
const projectSlug = (payload.project || 'unknown').toLowerCase().replace(/[^a-z0-9]/g, '-').slice(0, 20);
const sessionId = `${dateStr}-${timeStr}-${projectSlug}`;

// Build Notion page properties
const properties = {
  'Session ID': {
    title: [{ text: { content: sessionId } }]
  },
  'Goals': {
    rich_text: [{ text: { content: payload.goals || '' } }]
  },
  'Start Time': {
    date: { start: now }
  },
  'Status': {
    select: { name: 'Active' }
  },
  'AI Type': {
    select: { name: payload.ai_type || 'Claude' }
  },
  'Recording Format': {
    select: { name: payload.recording_format || 'asciinema' }
  }
};

// Add recording file path if provided
if (payload.recording_file_path) {
  properties['Recording File Path'] = {
    rich_text: [{ text: { content: payload.recording_file_path } }]
  };
}

// Project relation (requires page ID)
if (payload.project_id) {
  properties['Projects'] = {
    relation: [{ id: payload.project_id }]
  };
}

return [{
  json: {
    session_id: sessionId,
    notion_payload: {
      parent: { data_source_id: '2b43d603-acb6-8064-82f9-000b343a2e1c' },
      properties: properties
    }
  }
}];

// End Session - Step 1: Query Notion to find session by Session ID
const payload = $input.first().json.payload;
const now = new Date().toISOString();

// Query by Session ID (title field)
return [{
  json: {
    query: {
      endpoint: 'query_data_source',
      id: '2b43d603-acb6-8064-82f9-000b343a2e1c'
    },
    body: {
      filter: {
        property: 'Session ID',
        title: {
          equals: payload.session_id
        }
      },
      page_size: 1
    },
    end_time: now,
    session_id: payload.session_id
  }
}];

// List Sessions - Query sessions database
const payload = $input.first().json.payload;

const body = {
  page_size: payload.limit || 20
};

// Add status filter if provided
if (payload.status) {
  body.filter = {
    property: 'Status',
    select: {
      equals: payload.status
    }
  };
}

return [{
  json: {
    query: {
      endpoint: 'query_data_source',
      id: '2b43d603-acb6-8064-82f9-000b343a2e1c'
    },
    body: body
  }
}];

// List Projects - Query projects database
const payload = $input.first().json.payload;

const body = {
  page_size: payload.limit || 20
};

// Add status filter if provided
if (payload.status) {
  body.filter = {
    property: 'Status',
    select: {
      equals: payload.status
    }
  };
}

return [{
  json: {
    query: {
      endpoint: 'query_data_source',
      id: '2b23d603-acb6-80df-9e44-000bdb264067'
    },
    body: body
  }
}];

// Query Feedback - Simplified version
const payload = $input.first().json.payload;

const queryText = payload.query || '';
const learningIds = payload.relevant_learning_ids || [];

// TODO: Add HTTP Request node to actually store feedback in Supabase
// For now, just return success to unblock endpoint testing

return [{
  json: {
    success: true,
    message: 'Thank you for the feedback! This helps improve search quality.',
    query: queryText,
    relevant_learning_count: learningIds.length,
    note: 'Feedback logging to be implemented via HTTP Request node'
  }
}];

// Call Notion API wrapper to create page
const input = $input.first().json;

return [{
  json: {
    query: {
      endpoint: 'create_page',
      id: null
    },
    body: input.notion_payload
  }
}];

// Step 2: Extract page_id from query result and prepare update
const input = $input.first().json;
const updatePayload = $('Update Learning Logic').first().json.update_payload;
const now = new Date().toISOString();

// Extract page_id from query result
if (!input.results || input.results.length === 0) {
  throw new Error(`Learning not found: ${updatePayload.learning_id}. ` +
    `Query returned ${input.results ? input.results.length : 0} results. ` +
    `Make sure the learning_id exactly matches the Notion page title.`);
}

const pageId = input.results[0].id;

// Build update properties
const properties = {
  'Last Modified': {
    date: { start: now }
  }
};

// Update only provided fields
if (updatePayload.title) {
  properties['Title'] = {
    title: [{ text: { content: updatePayload.title } }]
  };
}

if (updatePayload.type) {
  properties['Type'] = {
    select: { name: updatePayload.type }
  };
}

if (updatePayload.content) {
  properties['Content'] = {
    rich_text: [{ text: { content: updatePayload.content } }]
  };
}

if (updatePayload.context) {
  properties['Context'] = {
    rich_text: [{ text: { content: updatePayload.context } }]
  };
}

if (updatePayload.confidence) {
  properties['Confidence'] = {
    select: { name: updatePayload.confidence }
  };
}

if (updatePayload.status) {
  properties['Status'] = {
    select: { name: updatePayload.status }
  };
}

if (updatePayload.dev_stream && Array.isArray(updatePayload.dev_stream)) {
  properties['Dev Stream'] = {
    multi_select: updatePayload.dev_stream.map(s => ({ name: s }))
  };
}

if (updatePayload.tags && Array.isArray(updatePayload.tags)) {
  properties['Tags'] = {
    multi_select: updatePayload.tags.map(t => ({ name: t }))
  };
}

if (updatePayload.related_files) {
  properties['Related Files'] = {
    rich_text: [{ text: { content: updatePayload.related_files } }]
  };
}

if (updatePayload.ai_accepted !== undefined) {
  properties['AI Accepted'] = {
    checkbox: updatePayload.ai_accepted
  };
}

return [{
  json: {
    query: {
      endpoint: 'update_page',
      id: pageId
    },
    body: {
      properties: properties
    }
  }
}];

// Step 2: Extract page_id from query result and prepare session update
const input = $input.first().json;
const endSessionData = $('End Session Logic').first().json;

// Extract page_id from query result
if (!input.results || input.results.length === 0) {
  throw new Error(`Session not found: ${endSessionData.session_id}`);
}

const pageId = input.results[0].id;

// Build update properties
const properties = {
  'End Time': {
    date: { start: endSessionData.end_time }
  },
  'Status': {
    select: { name: 'Completed' }
  }
};

return [{
  json: {
    query: {
      endpoint: 'update_page',
      id: pageId
    },
    body: {
      properties: properties
    }
  }
}];

// Format successful response
const input = $input.first().json;

let response = {
  success: true,
  data: input
};

// Extract title or session_id from created page if present
if (input.id && input.properties) {
  // This is a Notion page response
  if (input.properties['Title']) {
    response.title = input.properties['Title'].title[0]?.text?.content;
    response.page_id = input.id;
    response.url = input.url;
    response.message = `Learning "${response.title}" created successfully`;
  } else if (input.properties['Session ID']) {
    response.session_id = input.properties['Session ID'].title[0]?.text?.content;
    response.page_id = input.id;
    response.url = input.url;
    response.message = `Session ${response.session_id} started successfully`;
  } else {
    response.message = 'Updated successfully';
  }
} else if (input.results) {
  // This is a query result
  response.count = input.results.length;
  response.message = `Retrieved ${response.count} items`;
} else {
  response.message = 'Operation completed';
}

return [{ json: response }];

// Prepare Notion create page call for learning
const input = $input.first().json;

return [{
  json: {
    query: {
      endpoint: 'create_page',
      id: null
    },
    body: input.notion_payload
  }
}];

// Prepare data for embedding generation
const notionResponse = $input.first().json;
const captureData = $('Capture Learning Logic').first().json;
const originalPayload = $('Parse Request').first().json.payload;

// Extract learning content
const title = captureData.title || 'Untitled';
const content = originalPayload.content || '';
const context = originalPayload.context || '';

// Combine for embedding
const textForEmbedding = `${title}\n\n${content}\n\nContext: ${context}`;

// Build metadata
const metadata = {
    title: title,
    project: originalPayload.project || 'Unknown',
    type: originalPayload.type || 'technical',
    dev_stream: originalPayload.dev_stream || [],
    tags: originalPayload.tags || [],
    confidence: originalPayload.confidence || 'Medium',
    source_channel: originalPayload.source_channel || 'api',
    created_at: new Date().toISOString()
};

return [{
    json: {
        learning_id: title,
        content: textForEmbedding,
        metadata: metadata,
        notion_response: notionResponse
    }
}];

// Prepare Supabase insert
const embeddingData = $('Prepare Embedding Data').first().json;
const embeddingResponse = $input.first().json;

const embedding = embeddingResponse.data[0].embedding;

// Convert embedding array to proper format for Supabase vector type
const embeddingStr = `[${embedding.join(',')}]`;

return [{
    json: {
        learning_id: embeddingData.learning_id,
        content: embeddingData.content,
        embedding: embeddingStr,
        metadata: embeddingData.metadata,
        notion_response: embeddingData.notion_response
    }
}];

// Format capture_learning response
const supabaseData = $('Prepare Supabase Insert').first().json;
const notionResponse = supabaseData.notion_response;

return [{
    json: {
        success: true,
        title: supabaseData.learning_id,
        page_id: notionResponse.id,
        url: notionResponse.url,
        message: `Learning "${supabaseData.learning_id}" created successfully`,
        embedding_stored: true
    }
}];

// Prepare query embedding request
const payload = $input.first().json.payload;

return [{
    json: {
        query: payload.query,
        limit: payload.limit || 5,
        project: payload.project || null,
        openai_request: {
            model: 'text-embedding-3-small',
            input: payload.query
        }
    }
}];

// Prepare Supabase vector search
const queryData = $('Query Learnings Logic').first().json;
const embeddingResponse = $input.first().json;

const queryEmbedding = embeddingResponse.data[0].embedding;

return [{
    json: {
        query_text: queryData.query,
        query_embedding: queryEmbedding,
        match_count: queryData.limit,
        project_filter: queryData.project
    }
}];

// Format query results
const queryData = $('Prepare Vector Search').first().json;
const searchResults = $input.all();

return [{
    json: {
        success: true,
        query: queryData.query_text,
        count: searchResults.length,
        results: searchResults.map(item => ({
            learning_id: item.json.learning_id,
            content: item.json.content,
            similarity: item.json.similarity,
            metadata: item.json.metadata
        }))
    }
}];
